use std::time::Duration;

use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::upstream::Upstream;

pub const CALL_TIMEOUT: Duration = Duration::from_secs(300);
pub const RETRIES: u8 = 3;
pub const RETRY_WAIT: Duration = Duration::from_secs(5);

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Think {
    Off,
    Low,
    Medium,
    High,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Speaker {
    User,
    Assistant,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Message {
    pub speaker: Speaker,
    pub content: String,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize)]
pub struct Tokens {
    pub input: u64,
    pub output: u64,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Reply {
    pub text: String,
    pub tokens: Tokens,
}

#[derive(Debug, Clone, Copy)]
pub struct Call<'a> {
    pub model: &'a str,
    pub think: Think,
    pub temperature: f32,
    pub system: &'a str,
    pub messages: &'a [Message],
}

#[derive(Debug, Clone)]
pub struct Chat {
    base: String,
    http: reqwest::Client,
}

impl Tokens {
    pub fn plus(self, other: Tokens) -> Tokens {
        Tokens {
            input: self.input + other.input,
            output: self.output + other.output,
        }
    }
}

impl Chat {
    pub fn new(base: String, http: reqwest::Client) -> Chat {
        debug_assert!(!base.ends_with('/'), "Chat.new: base has no trailing slash");
        Chat { base, http }
    }

    pub fn from_env() -> Chat {
        Chat::new(
            crate::qdrant::env_base("OLLAMA_URL", "http://localhost:11434"),
            reqwest::Client::new(),
        )
    }

    pub async fn send(&self, call: &Call<'_>) -> Result<Reply, Upstream> {
        debug_assert!(
            call.messages.last().is_some_and(|m| m.speaker == Speaker::User),
            "Chat.send: the last message is the user's"
        );
        let result: Result<Reply, Upstream> = todo!("Chat.send");
        result
    }
}

pub fn body(call: &Call<'_>) -> Value {
    let result: Value = todo!("body");
    debug_assert!(
        result["messages"][0]["role"] == "system",
        "body: the system prompt goes first, with the role system"
    );
    debug_assert!(
        result.get("think").is_some(),
        "body: the thinking level is always sent"
    );
    debug_assert!(
        result["stream"] == false,
        "body: one reply, no stream"
    );
    result
}

pub fn is_retried(status: u16) -> bool {
    status == 429 || (500..600).contains(&status)
}

